import {doodle} from './art.js';
const memories=[
{id:'bird',chapter:1,name:'Um primeiro voo',icon:'bird',line:'Ele caiu. Lior sorriu.',text:'Um pássaro que não voava deu nome a uma gaveta cheia de possibilidades. Algumas tentativas merecem ser guardadas.'},
{id:'music',chapter:2,name:'A mesma melodia',icon:'box',line:'Uma lembrança não pede uma versão melhor.',text:'Nessa queria ouvir a música de antes. Naquele dia, cuidar foi deixar algo continuar sendo o que era.'},
{id:'question',chapter:5,name:'Uma pergunta pequena',icon:'letter',line:'Melhor para quem?',text:'Íria fez uma pergunta que não cabia na pressa de Lior. Ela continuou por perto mesmo quando ninguém a dizia.'},
{id:'light',chapter:9,name:'Uma vitória quieta',icon:'lamp',line:'Pronto. No prazo. O suficiente.',text:'A luminária foi entregue. O desenho das modificações ficou na gaveta. Não houve aplausos, mas houve uma pequena satisfação.'}
];
let saved=new Set();try{const x=JSON.parse(localStorage.getItem('lior-discoveries-v1')||'[]');if(Array.isArray(x))saved=new Set(x.filter(v=>memories.some(m=>m.id===v)))}catch{}
const backs=[
 'E se a pessoa sentir saudade de dois lugares? Vou precisar de outra janela.',
 'A asa esquerda ficou amassada. Ele ainda parece bem satisfeito consigo mesmo.',
 'Da próxima vez, deixar o alicate na gaveta até a pessoa acabar de falar.',
 'Ela pegou meu lápis, circulou uma opção e foi buscar café. Assim também vale?',
 'Tem uma mancha de tinta perto da última flor. É do meu dedo. Deixar também.',
 'Quando ela saiu, fiquei um tempão com aquela música na cabeça.',
 'Perguntei pra minha mãe. Ela gosta da cozinha exatamente onde está. Bom saber.',
 'Guardei o lápis antes de inventar mais alguma coisa.'
];
export function noteExtras(i){return '<div class="note-secret" hidden><span class="eyebrow">NO VERSO, COM OUTRA TINTA</span><p>'+backs[i%backs.length]+'</p><span class="handwriting">L. Bellamy</span></div><button class="flip-note" aria-pressed="false">Virar o papel ↻</button>'}
function collection(){return '<section class="keepsakes" aria-labelledby="keepsake-title"><div class="keepsake-heading"><div><span class="eyebrow">COISAS QUE FICARAM COM VOCÊ</span><h2 id="keepsake-title">A sua gaveta<br><em>dos talvez.</em></h2></div><p>Há pequenas lembranças nas margens da história.<br>Guarde as que encontrar. Elas esperam aqui.</p></div><div class="keepsake-rail"><span>'+saved.size+' / 4 lembranças</span><span>ENCONTRADAS, NÃO FABRICADAS</span></div><div class="keepsake-grid">'+memories.map((m,i)=>saved.has(m.id)?'<button class="keepsake found" data-memory="'+m.id+'"><span class="keepsake-number">0'+(i+1)+'</span>'+doodle(m.icon)+'<h3>'+m.name+'</h3><span>abrir lembrança ↗</span></button>':'<a class="keepsake missing" href="#/historia/'+m.chapter+'"><span class="keepsake-number">0'+(i+1)+'</span><span class="missing-outline">?</span><h3>Um espaço reservado.</h3><span>uma pista no capítulo '+String(m.chapter).padStart(2,'0')+' ↗</span></a>').join('')+'</div><p class="keepsake-foot">Suas descobertas ficam neste navegador. '+(saved.size===4?'“Você guarda coisas pequenas também. Agora entende a gaveta.”':'“Não precisa encontrar tudo hoje.”')+'</p></section>'}
export function exploreRoute(path){document.querySelector('#memory-dialog')?.close();if(path==='caderno'){document.querySelector('.note-grid').insertAdjacentHTML('afterend',collection())}if(path==='historia'){memories.forEach(m=>{const article=document.querySelector('#chapter-'+m.chapter);if(!article)return;const phrases={bird:'“Você viu? Ele tentou.”',music:'“Não quero uma música melhor, menino. Quero a mesma.”',question:'“Melhor para quem?”',light:'Naquela noite, colocou o desenho das modificações na gaveta dos talvez.'};const paragraph=[...article.querySelectorAll(':scope > p')].find(p=>p.textContent===phrases[m.id]);if(!paragraph)return;paragraph.classList.add('memory-passage');paragraph.insertAdjacentHTML('beforeend','<button data-find="'+m.id+'" class="memory-mark '+(saved.has(m.id)?'is-kept':'')+'" aria-label="'+(saved.has(m.id)?'Rever':'Descobrir')+' lembrança: '+m.name+'" title="'+(saved.has(m.id)?'Lembrança guardada':'Guardar uma lembrança')+'">'+doodle(m.icon)+'<span aria-hidden="true" class="memory-mark-sign">'+(saved.has(m.id)?'✓':'+')+'</span></button>')})}}
function showMemory(id,collect){const m=memories.find(m=>m.id===id);if(!m)return;let dialog=document.querySelector('#memory-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='memory-dialog';dialog.setAttribute('aria-labelledby','memory-title');document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})}
dialog.classList.remove('memory-collected');dialog.innerHTML='<button class="memory-close" aria-label="Fechar lembrança">×</button><span class="eyebrow">ENTRE AS PÁGINAS / CAPÍTULO '+String(m.chapter).padStart(2,'0')+'</span><div class="memory-art">'+doodle(m.icon)+'</div><h2 id="memory-title">'+m.name+'</h2><p class="memory-line">'+m.line+'</p><p>'+m.text+'</p><div class="memory-actions">'+(!saved.has(id)&&collect?'<button class="ink-button" data-save-memory="'+id+'">Guardar na minha gaveta ↗</button>':'<span class="saved-seal">GUARDADO COM CUIDADO</span>')+'<a href="#/caderno" class="memory-notebook">Ver minha gaveta →</a></div><p class="memory-status" role="status"></p>';
dialog.querySelector('.memory-close').onclick=()=>dialog.close();dialog.showModal()}
document.addEventListener('click',e=>{
const flip=e.target.closest('.flip-note');if(flip){const body=flip.closest('#note-body');const back=flip.getAttribute('aria-pressed')!=='true';flip.setAttribute('aria-pressed',String(back));body.classList.toggle('show-note-back',back);body.querySelector('.note-secret').hidden=!back;body.querySelector('.dialog-quote').hidden=back;body.querySelector('.dialog-doodle').hidden=back;body.classList.remove('paper-turning');void body.offsetWidth;body.classList.add('paper-turning');flip.textContent=back?'Voltar à frente ↶':'Virar o papel ↻';return}
const find=e.target.closest('[data-find]');if(find){showMemory(find.dataset.find,true);return}
const memory=e.target.closest('[data-memory]');if(memory){showMemory(memory.dataset.memory,false);return}
const save=e.target.closest('[data-save-memory]');if(save){saved.add(save.dataset.saveMemory);const mark=document.querySelector('[data-find="'+save.dataset.saveMemory+'"]');if(mark){mark.classList.add('is-kept');mark.title='Lembrança guardada';mark.setAttribute('aria-label',mark.getAttribute('aria-label').replace('Descobrir','Rever'));mark.querySelector('.memory-mark-sign').textContent='✓'}let persisted=true;try{localStorage.setItem('lior-discoveries-v1',JSON.stringify([...saved]))}catch{persisted=false}save.disabled=true;save.textContent='Guardado com cuidado ✓';document.querySelector('.memory-status').textContent=persisted?'Uma lembrança a mais na sua gaveta.':'Guardado nesta visita. O navegador não permitiu salvar para depois.';document.querySelector('#memory-dialog').classList.add('memory-collected');return}
if(e.target.closest('.memory-notebook')){document.querySelector('#memory-dialog')?.close()}
});
